<script setup>
import { ref, onMounted, watch } from 'vue'
import { Megaphone, ArrowUpRight, MessageSquareText, Send, Check, Leaf } from '@lucide/vue'
import { state, api, attempt, requireStudent, notify } from '../state'
const notices=ref([]), feedback=ref([]), content=ref(''), windowId=ref('1'), sending=ref(false)
async function loadFeedback(){feedback.value=state.account?.role==='STUDENT'?await api('/student/feedback'):[]}
async function submit(){if(!requireStudent()||sending.value)return;sending.value=true;await attempt(async()=>{await api('/student/feedback',{method:'POST',body:{windowId:windowId.value,content:content.value}});content.value='';notify('你的反馈已送达对应窗口');await loadFeedback()});sending.value=false}
watch(()=>state.account?.userId,()=>attempt(loadFeedback))
onMounted(()=>attempt(async()=>{notices.value=await api('/public/notices');await loadFeedback()}))
</script>
<template><div class="page-wrap inner-page"><div class="page-title"><div><p class="eyebrow">A LITTLE NEWS FROM YOUR CANTEEN</p><h1>校园公告<span class="title-dot">.</span></h1><p>关于好好吃饭，还有这些小事想告诉你。</p></div><span class="page-title-icon"><Megaphone :size="32" :stroke-width="1.3" /></span></div><div class="notices-layout"><div><article v-for="notice in notices" :key="notice.id" class="notice-card"><div><span class="notice-category">{{ notice.category }}</span><time>{{ notice.publishedAt }}</time></div><h2>{{ notice.title }}</h2><p>{{ notice.content }}</p><span class="notice-signature"><Leaf :size="13" />禾序饭堂 · 校园餐饮服务</span></article></div><aside class="feedback-panel"><span class="eyebrow">WE ARE LISTENING</span><h2><MessageSquareText :size="23" />你的声音，我们听见。</h2><p>想给窗口提个建议，或反馈一次就餐体验？在这里留句话。</p><form @submit.prevent="submit"><label>想对哪个窗口说<select v-model="windowId"><option v-for="window in state.windows" :key="window.id" :value="window.id">{{ window.canteenName }} · {{ window.name }}</option></select></label><label>你的建议<textarea v-model="content" required maxlength="500" rows="5" placeholder="请写下你遇到的问题或建议。" /></label><button class="button button-primary full" :disabled="sending">{{ sending?'发送中':'把建议告诉我们' }}<Send :size="15" /></button></form><div v-if="feedback.length" class="feedback-history"><h3>我的反馈</h3><article v-for="item in feedback" :key="item.id"><small>{{ item.windowName }} · {{ item.createdAt }}</small><p>{{ item.content }}</p><div v-if="item.reply" class="feedback-reply"><Check :size="13" /><span>{{ item.reply }}</span></div><span v-else class="tiny muted">窗口工作人员将尽快回复</span></article></div></aside></div></div></template>
